item.text:
{
  "cases": [
    {
      "id": "C1",
      "probes": [
        {
          "id": "repeat_test",
          "label": "Not established",
          "quote": "The report does not say whether runs were repeated.",
          "reason": "Missing reporting does not establish whether repeated testing occurred."
        },
        {
          "id": "stable",
          "label": "Not established",
          "quote": "The tested system scored 70% in one reported run.",
          "reason": "One reported score does not establish stability across runs."
        }
      ],
      "instrument_review": "MESA 14: repeated testing is unclear. MESA 16: no estimate of variation across runs is supplied."
    },
    {
      "id": "C2",
      "probes": [
        {
          "id": "repeat_test",
          "label": "Contradicted",
          "quote": "they ran the evaluation exactly once and did not repeat it",
          "reason": "The passage explicitly states that repeated testing did not occur."
        },
        {
          "id": "stable",
          "label": "Not established",
          "quote": "they ran the evaluation exactly once and did not repeat it",
          "reason": "Without repeated results, stability remains unknown; absence of testing does not demonstrate instability."
        }
      ],
      "instrument_review": "MESA 14: No, repeated testing explicitly did not occur. MESA 16: the single run provides no estimate of variation across runs."
    },
    {
      "id": "C3",
      "probes": [
        {
          "id": "repeat_test",
          "label": "Supported",
          "quote": "They also repeated the evaluation ten times with the same system, inputs, instructions, resources, and settings.",
          "reason": "Repeated evaluations used the same stated conditions."
        },
        {
          "id": "stable",
          "label": "Supported",
          "quote": "Scores ranged from 69% to 71%.",
          "reason": "The two-percentage-point range meets the report's stated stability criterion."
        }
      ],
      "instrument_review": "MESA 14: Yes, repeated testing occurred. MESA 16: the observed range supports stability under the stated criterion for this comparison."
    },
    {
      "id": "C4",
      "probes": [
        {
          "id": "repeat_test",
          "label": "Supported",
          "quote": "They also repeated the evaluation ten times with the same system, inputs, instructions, resources, and settings.",
          "reason": "Repeated testing occurred despite unfavourable stability results."
        },
        {
          "id": "stable",
          "label": "Contradicted",
          "quote": "Scores ranged from 20% to 90%.",
          "reason": "The observed range exceeds the stated maximum of two percentage points."
        }
      ],
      "instrument_review": "MESA 14: Yes, testing occurred. MESA 16: the reported variation directly conflicts with stability under the report's criterion."
    },
    {
      "id": "C5",
      "probes": [
        {
          "id": "repeat_test",
          "label": "Not established",
          "quote": "The report does not say whether runs were repeated.",
          "reason": "Installation instructions supply no evidence of repeated testing."
        },
        {
          "id": "stable",
          "label": "Not established",
          "quote": "They report no additional evaluation results.",
          "reason": "The added instructions provide no results establishing stability."
        }
      ],
      "instrument_review": "MESA 22: installation instructions help describe setup. They do not resolve the missing evidence about repeated testing and score variation in MESA 14 and 16."
    },
    {
      "id": "C6",
      "probes": [
        {
          "id": "narrow",
          "label": "Supported",
          "quote": "System A solves 80 puzzles and system B solves 60 in the reported evaluation.",
          "reason": "A solved more evaluated puzzles under the stated scoring and conditions."
        },
        {
          "id": "broad",
          "label": "Not established",
          "quote": "Only grid puzzles were tested; no findings about other tasks are supplied.",
          "reason": "These results do not establish comparative general intelligence across domains."
        }
      ],
      "instrument_review": "MESA 2 and 25: the stated intended use fits the observed grid-puzzle comparison. MESA 20: broader performance is not established."
    },
    {
      "id": "C7",
      "probes": [
        {
          "id": "narrow",
          "label": "Supported",
          "quote": "System A solves 80 puzzles and system B solves 60 in the reported evaluation.",
          "reason": "The reported results support A's better performance on the evaluated puzzles."
        },
        {
          "id": "broad",
          "label": "Not established",
          "quote": "Only grid puzzles were tested; no findings about other tasks are supplied.",
          "reason": "A broader intended use does not supply evidence of general intelligence across domains."
        }
      ],
      "instrument_review": "MESA 9 and 20: grid-only evidence does not establish coverage or performance across domains. MESA 25: using these results to select for greater general intelligence would exceed the supplied evidence."
    },
    {
      "id": "C8",
      "probes": [
        {
          "id": "before",
          "label": "Not established",
          "quote": "Initially, only test scores were available.",
          "reason": "The initial scores alone supply no demonstrated link to improved real workshop decisions."
        },
        {
          "id": "after",
          "label": "Supported",
          "quote": "With A, 90% of decisions were correct; with B, 70%.",
          "reason": "The randomized trial and reported difference interval support better correctness with A in the studied workshop and conditions."
        },
        {
          "id": "safety",
          "label": "Not established",
          "quote": "Time and safety outcomes were not measured.",
          "reason": "Improved decision correctness does not establish an unmeasured safety benefit."
        }
      ],
      "instrument_review": "MESA 20: the later trial adds evidence for workshop decision correctness beyond initial test scores. MESA 16: the difference interval supports that comparison. MESA 25: conclusions should remain limited to correctness in the studied setting."
    }
  ],
  "closing_note": "No material instruction ambiguity remained. Probe labels classify statements; whether testing occurred is distinct from whether its results support stability."
}
